{
  "book_code": "2ES",
  "verses": [
    {
      "chapter": 10,
      "text_ar": "ما بالُكَ مضطرباً؟ ولِمَ قلبُكَ وفكرُكَ حائران؟",
      "verse": 31
    },
    {
      "chapter": 10,
      "text_ar": "فقلتُ: لأنَّكَ تركتَني، ومع أني فعلتُ بحسبِ كلامِكَ وخرجتُ إلى الحقلِ، ها أنا قد رأيتُ وما زلتُ أرى ما لا أستطيعُ تفسيرَهُ.",
      "verse": 32
    },
    {
      "chapter": 10,
      "text_ar": "فقالَ لي: قِفْ كالرَّجلِ، وسأُعلِّمُكَ.",
      "verse": 33
    },
    {
      "chapter": 10,
      "text_ar": "فقلتُ: تَكلَّمْ يا سيدي، ولا تُهملْني لئلا أموتَ قبلَ أواني.",
      "verse": 34
    },
    {
      "chapter": 10,
      "text_ar": "فإني رأيتُ ما لم أكنْ أعرفُهُ، وسمعتُ ما لا أدركُهُ.",
      "verse": 35
    }
  ]
}
